package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

import java.util.Arrays;
import java.util.List;

class LoanMapper {

    private static final String REASON_CODE_DELIMITER = ",";

    Loan toDomain(LoanJpaEntity entity) {
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(), entity.getLoanedAt(),
                entity.getDueAt(), toDomain(entity.getCreditCheck()), entity.getReturnedAt());
    }

    LoanJpaEntity toEntity(Loan loan) {
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(), loan.getDueAt(),
                toEmbeddable(loan.getCreditCheck()), loan.getReturnedAt().orElse(null));
    }

    private CreditCheck toDomain(CreditCheckEmbeddable embeddable) {
        List<String> reasonCodes = embeddable.getReasonCodes().isEmpty()
                ? List.of()
                : Arrays.asList(embeddable.getReasonCodes().split(REASON_CODE_DELIMITER));
        return new CreditCheck(embeddable.isApproved(), embeddable.getScore(), reasonCodes, embeddable.getCheckedAt(),
                embeddable.getProviderName(), embeddable.getProviderVersion());
    }

    private CreditCheckEmbeddable toEmbeddable(CreditCheck creditCheck) {
        return new CreditCheckEmbeddable(creditCheck.approved(), creditCheck.score(),
                String.join(REASON_CODE_DELIMITER, creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }
}
