package com.example.lending.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;

import java.time.Instant;

@Embeddable
public class CreditCheckEmbeddable {

    @Column(name = "credit_approved", nullable = false)
    private boolean approved;

    @Column(name = "credit_score", nullable = false)
    private int score;

    // 사유 코드 목록을 쉼표로 이어 저장한다.
    @Column(name = "credit_reason_codes", nullable = false)
    private String reasonCodes;

    @Column(name = "credit_checked_at", nullable = false)
    private Instant checkedAt;

    @Column(name = "credit_provider_name")
    private String providerName;

    @Column(name = "credit_provider_version")
    private String providerVersion;

    protected CreditCheckEmbeddable() {
    }

    public CreditCheckEmbeddable(boolean approved, int score, String reasonCodes, Instant checkedAt,
                                 String providerName, String providerVersion) {
        this.approved = approved;
        this.score = score;
        this.reasonCodes = reasonCodes;
        this.checkedAt = checkedAt;
        this.providerName = providerName;
        this.providerVersion = providerVersion;
    }

    public boolean isApproved() {
        return approved;
    }

    public int getScore() {
        return score;
    }

    public String getReasonCodes() {
        return reasonCodes;
    }

    public Instant getCheckedAt() {
        return checkedAt;
    }

    public String getProviderName() {
        return providerName;
    }

    public String getProviderVersion() {
        return providerVersion;
    }
}
