package com.example.lending.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.UniqueConstraint;

import java.util.UUID;

@Entity
@Table(name = "reservation", uniqueConstraints = @UniqueConstraint(columnNames = {"bookId", "sequence"}))
public class ReservationJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private long sequence;

    @Column(nullable = false)
    private boolean fulfilled;

    protected ReservationJpaEntity() {
    }

    public ReservationJpaEntity(UUID id, UUID bookId, UUID memberId, long sequence, boolean fulfilled) {
        this.id = id;
        this.bookId = bookId;
