package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;

import java.time.Instant;
import java.util.Arrays;
import java.util.List;

@Embeddable
class CreditCheckEmbeddable {

    private static final String REASON_CODE_DELIMITER = ",";

    @Column(name = "credit_approved", nullable = false)
    private boolean approved;

    @Column(name = "credit_score", nullable = false)
    private int score;

    // 사유 코드 목록을 쉼표로 이어 저장한다.
    @Column(name = "credit_reason_codes", nullable = false)
    private String reasonCodes;

    @Column(name = "credit_checked_at", nullable = false)
    private Instant checkedAt;

    @Column(name = "credit_provider_name")
    private String providerName;

    @Column(name = "credit_provider_version")
    private String providerVersion;

    protected CreditCheckEmbeddable() {
    }

    static CreditCheckEmbeddable from(CreditCheck creditCheck) {
        CreditCheckEmbeddable embeddable = new CreditCheckEmbeddable();
        embeddable.approved = creditCheck.approved();
        embeddable.score = creditCheck.score();
        embeddable.reasonCodes = String.join(REASON_CODE_DELIMITER, creditCheck.reasonCodes());
        embeddable.checkedAt = creditCheck.checkedAt();
        embeddable.providerName = creditCheck.providerName();
        embeddable.providerVersion = creditCheck.providerVersion();
        return embeddable;
    }

    CreditCheck toDomain() {
        List<String> codes = reasonCodes.isEmpty() ? List.of() : Arrays.asList(reasonCodes.split(REASON_CODE_DELIMITER));
        return new CreditCheck(approved, score, codes, checkedAt, providerName, providerVersion);
    }
}
